FILAS_METAODS = (
    ('id', 'ods_id', 'descripcion', 'estado', 'fecha_creacion', 'fecha_actualizacion'),
    [
        (1, 8, '16.6 Crear a todos los niveles instituciones eficaces y transparentes que rindan cuentas', True, '2026-06-08T20:02:58.056092+00:00', '2026-07-02T04:39:21.085298+00:00'),
        (2, 8, '16.10 Garantizar el acceso público a la información y proteger las libertades fundamentales, de conformidad con las leyes nacionales y los acuerdos internacionales', True, '2026-06-08T20:02:58.06458+00:00', '2026-07-02T04:39:21.089952+00:00'),
        (3, 8, '16.b Promover y aplicar leyes y políticas no discriminatorias en favor del desarrollo sostenible', True, '2026-06-08T20:02:58.071753+00:00', '2026-07-02T04:39:21.093226+00:00'),
        (4, 8, '16.3 Promover el estado de derecho en los planos nacional e internacional y garantizar la igualdad en el acceso a la justicia para todos', True, '2026-06-08T20:02:58.079754+00:00', '2026-07-02T04:39:21.096499+00:00'),
        (5, 8, '16.1 Reducir significativamente todas las formas de violencia y las correspondientes tasas de mortalidad en todo el mundo', True, '2026-06-08T20:02:58.087441+00:00', '2026-07-02T04:39:21.099779+00:00'),
        (6, 1, '1.5 De aquí a 2030, fomentar la resiliencia de los pobres y las personas que se encuentran en situaciones de vulnerabilidad y reducir su exposición y vulnerabilidad a los fenómenos extremos relacionados con el clima y otras perturbaciones y desastres económicos, sociales y ambientales', True, '2026-06-08T20:02:58.095055+00:00', '2026-07-02T04:39:21.103105+00:00'),
        (7, 2, '10.2 De aquí a 2030, potenciar y promover la inclusión social, económica y política de todas las personas, independientemente de su edad, sexo, discapacidad, raza, etnia, origen, religión o situación económica u otra condición', True, '2026-06-08T20:02:58.101269+00:00', '2026-07-02T04:39:21.106879+00:00'),
        (8, 12, '4.7 De aquí a 2030, asegurar que todos los alumnos adquieran los conocimientos teóricos y prácticos necesarios para promover el desarrollo sostenible, entre otras cosas mediante la educación para el desarrollo sostenible y los estilos de vida sostenibles, los derechos humanos, la igualdad de género, la promoción de una cultura de paz y no violencia, la ciudadanía mundial y la valoración de la diversidad cultural y la contribución de la cultura al desarrollo sostenible', True, '2026-06-08T20:02:58.107844+00:00', '2026-07-02T04:39:21.110241+00:00'),
        (9, 3, '11.b De aquí a 2020, aumentar considerablemente el número de ciudades y asentamientos humanos que adoptan e implementan políticas y planes integrados para promover la inclusión, el uso eficiente de los recursos, la mitigación del cambio climático y la adaptación a él y la resiliencia ante los desastres, y desarrollar y poner en práctica, en consonancia con el Marco de Sendai para la Reducción del Riesgo de Desastres 2015-2030, la gestión integral de los riesgos de desastre a todos los niveles', True, '2026-06-08T20:02:58.115978+00:00', '2026-07-02T04:39:21.113595+00:00'),
        (10, 9, '17.14 Mejorar la coherencia normativa para el desarrollo sostenible', True, '2026-06-08T20:02:58.122863+00:00', '2026-07-02T04:39:21.116931+00:00'),
        (11, 9, '17.7 Promover el desarrollo de tecnologías ecológicamente racionales y su transferencia, divulgación y difusión a los países en desarrollo en condiciones favorables, incluso en condiciones concesionarias y preferenciales, por mutuo acuerdo', True, '2026-06-08T20:02:58.129321+00:00', '2026-07-02T04:39:21.120196+00:00'),
        (12, 9, '17.18 Para 2020, mejorar la prestación de apoyo para el fomento de la capacidad a los países en desarrollo, incluidos los países menos adelantados y los pequeños Estados insulares en desarrollo, con miras a aumentar de forma significativa la disponibilidad de datos oportunos, fiables y de alta calidad desglosados por grupos de ingresos, género, edad, raza, origen étnico, condición migratoria, discapacidad, ubicación geográfica y otras características pertinentes en los contextos nacionales', True, '2026-06-08T20:02:58.136318+00:00', '2026-07-02T04:39:21.124445+00:00'),
        (13, 9, '17.17 Alentar y promover la constitución de alianzas eficaces en las esferas pública, público-privada y de la sociedad civil, aprovechando la experiencia y las estrategias de obtención de recursos de las asociaciones', True, '2026-06-08T20:02:58.142322+00:00', '2026-07-02T04:39:21.12945+00:00'),
        (14, 9, '17.9 Aumentar el apoyo internacional a la ejecución de programas de fomento de la capacidad eficaces y con objetivos concretos en los países en desarrollo a fin de apoyar los planes nacionales orientados a aplicar todos los Objetivos de Desarrollo Sostenible, incluso mediante la cooperación Norte-Sur, Sur-Sur y triangular', True, '2026-06-08T20:02:58.149476+00:00', '2026-07-02T04:39:21.133566+00:00'),
        (15, 5, '13.3 Mejorar la educación, la sensibilización y la capacidad humana e institucional respecto de la mitigación del cambio climático, la adaptación a él, la reducción de sus efectos y la alerta temprana', True, '2026-06-08T20:02:58.156987+00:00', '2026-07-02T04:39:21.137016+00:00'),
        (16, 5, '13.1 Fortalecer la resiliencia y la capacidad de adaptación a los riesgos relacionados con el clima y los desastres naturales en todos los países', True, '2026-06-08T20:02:58.165481+00:00', '2026-07-02T04:39:21.140349+00:00'),
        (17, 13, '5.2 Eliminar todas las formas de violencia contra todas las mujeres y las niñas en los ámbitos público y privado, incluidas la trata y la explotación sexual y otros tipos de explotación', True, '2026-06-08T20:02:58.172646+00:00', '2026-07-02T04:39:21.14377+00:00'),
        (18, 13, '5.c Aprobar y fortalecer políticas acertadas y leyes aplicables para promover la igualdad de género y el empoderamiento de todas las mujeres y las niñas a todos los niveles', True, '2026-06-08T20:02:58.181352+00:00', '2026-07-02T04:39:21.147164+00:00'),
        (19, 9, '17.3 Movilizar recursos financieros adicionales procedentes de múltiples fuentes para los países en desarrollo', True, '2026-06-08T20:02:58.188709+00:00', '2026-07-02T04:39:21.150288+00:00'),
        (20, 12, '4.b De aquí a 2020, aumentar considerablemente a nivel mundial el número de becas disponibles para los países en desarrollo, en particular los países menos adelantados, los pequeños Estados insulares en desarrollo y los países africanos, a fin de que sus estudiantes puedan matricularse en programas de enseñanza superior, incluidos programas de formación profesional y programas técnicos, científicos, de ingeniería y de tecnología de la información y las comunicaciones, de países desarrollados y otros países en desarrollo', True, '2026-06-08T20:02:58.195706+00:00', '2026-07-02T04:39:21.153678+00:00'),
        (21, 9, '17.5 Adoptar y aplicar sistemas de promoción de las inversiones en favor de los países menos adelantados', True, '2026-06-08T20:02:58.202148+00:00', '2026-07-02T04:39:21.15702+00:00'),
        (22, 9, '17.16 Fortalecer la Alianza Mundial para el Desarrollo Sostenible, complementada por alianzas entre múltiples interesados que movilicen y promuevan el intercambio de conocimientos, capacidad técnica, tecnología y recursos financieros, a fin de apoyar el logro de los Objetivos de Desarrollo Sostenible en todos los países, en particular los países en desarrollo', True, '2026-06-08T20:02:58.210504+00:00', '2026-07-02T04:39:21.160842+00:00'),
        (23, 17, '9.1 Desarrollar infraestructuras fiables, sostenibles, resilientes y de calidad, incluidas infraestructuras regionales y transfronterizas, para apoyar el desarrollo económico y el bienestar humano, haciendo especial hincapié en el acceso asequible y equitativo para todos', True, '2026-06-08T20:02:58.217093+00:00', '2026-07-02T04:39:21.163993+00:00'),
        (24, 10, '2.4 De aquí a 2030, asegurar la sostenibilidad de los sistemas de producción de alimentos y aplicar prácticas agrícolas resilientes que aumenten la productividad y la producción, contribuyan al mantenimiento de los ecosistemas, fortalezcan la capacidad de adaptación al cambio climático, los fenómenos meteorológicos extremos, las sequías, las inundaciones y otros desastres, y mejoren progresivamente la calidad de la tierra y el suelo', True, '2026-06-08T20:02:58.222513+00:00', '2026-07-02T04:39:21.167703+00:00'),
        (25, 1, '1.4 De aquí a 2030, garantizar que todos los hombres tengan los mismos derechos a los recursos económicos y acceso a los servicios básicos, la propiedad y el control de la tierra y otros bienes, la herencia, los recursos naturales, las nuevas tecnologías apropiadas y los servicios financieros, incluida la microfinanciación', True, '2026-06-08T20:02:58.22855+00:00', '2026-07-02T04:39:21.1721+00:00'),
        (26, 7, '15.a Movilizar y aumentar significativamente los recursos financieros procedentes de todas las fuentes para conservar y utilizar de forma sostenible la biodiversidad y los ecosistemas', True, '2026-06-08T20:02:58.235923+00:00', '2026-07-02T04:39:21.177006+00:00'),
        (27, 16, '8.4 Mejorar progresivamente, de aquí a 2030, la producción y el consumo eficientes de los recursos mundiales y procurar desvincular el crecimiento económico de la degradación del medio ambiente, conforme al Marco Decenal de Programas sobre Modalidades de Consumo y Producción Sostenibles, empezando por los países desarrollados', True, '2026-06-08T20:02:58.243261+00:00', '2026-07-02T04:39:21.181655+00:00'),
        (28, 5, '13.a Cumplir el compromiso de los países desarrollados que son partes en la Convención Marco de las Naciones Unidas sobre el Cambio Climático de lograr para el año 2020 el objetivo de movilizar conjuntamente 100', True, '2026-06-08T20:02:58.249029+00:00', '2026-07-02T04:39:21.185529+00:00'),
        (29, 8, '16.a Fortalecer las instituciones nacionales pertinentes, incluso mediante la cooperación internacional, con miras a crear capacidad a todos los niveles, en particular en los países en desarrollo, para prevenir la violencia y combatir el terrorismo y la delincuencia', True, '2026-06-08T20:02:58.256296+00:00', '2026-07-02T04:39:21.189493+00:00'),
        (30, 11, '3.8 Lograr la cobertura sanitaria universal, incluida la protección contra los riesgos financieros, el acceso a servicios de salud esenciales de calidad y el acceso a medicamentos y vacunas inocuos, eficaces, asequibles y de calidad para todos', True, '2026-06-08T20:02:58.263236+00:00', '2026-07-02T04:39:21.193437+00:00'),
        (31, 12, '4.1 De aquí a 2030, asegurar que todas las niñas y todos los niños terminen la enseñanza primaria y secundaria, que ha de ser gratuita, equitativa y de calidad y producir resultados de aprendizaje pertinentes y efectivos', True, '2026-06-08T20:02:58.26943+00:00', '2026-07-02T04:39:21.197312+00:00'),
        (32, 8, '16.4 De aquí a 2030, reducir significativamente las corrientes financieras y de armas ilícitas, fortalecer la recuperación y devolución de los activos robados y luchar contra todas las formas de delincuencia organizada', True, '2026-06-08T20:02:58.276539+00:00', '2026-07-02T04:39:21.20135+00:00'),
        (33, 3, '11.a Apoyar los vinculos economicos, sociales y ambientales positivos entre las zonas urbanas, periurbanas, y rurales mediante el fortalecimiento de la planificación del desarrollo nacional y regional', True, '2026-06-08T20:02:58.284307+00:00', '2026-07-02T04:39:21.205882+00:00'),
        (34, 10, '2.3 De aquí a 2030, duplicar la productividad agrícola y los ingresos de los productores de alimentos en pequeña escala, en particular las mujeres, los pueblos indígenas, los agricultores familiares, los ganaderos y los pescadores, entre otras cosas mediante un acceso seguro y equitativo a las tierras, a otros recursos e insumos de producción y a los conocimientos, los servicios financieros, los mercados y las oportunidades para añadir valor y obtener empleos no agrícolas', True, '2026-06-08T20:02:58.291258+00:00', '2026-07-02T04:39:21.210001+00:00'),
        (35, 1, '1.2 De aquí a 2030, reducir al menos a la mitad la proporción de hombres, mujeres y niños de todas las edades que viven en la pobreza en todas sus dimensiones con arreglo a las definiciones nacionales', True, '2026-06-08T20:02:58.298915+00:00', '2026-07-02T04:39:21.214153+00:00'),
        (36, 10, '2.a Aumentar, incluso mediante una mayor cooperación internacional, las inversiones en infraestructura rural, investigación y servicios de extensión agrícola, desarrollo tecnológico y bancos de genes de plantas y ganado a fin de mejorar la capacidad de producción agropecuaria en los países en desarrollo, particularmente en los países menos adelantados', True, '2026-06-08T20:02:58.305655+00:00', '2026-07-02T04:39:21.218124+00:00'),
        (37, 2, '10.1 De aquí a 2030, lograr progresivamente y mantener el crecimiento de los ingresos del 40% más pobre de la población a una tasa superior a la media nacional', True, '2026-06-08T20:02:58.312913+00:00', '2026-07-02T04:39:21.221957+00:00'),
        (38, 14, '6.2 De aquí a 2030, lograr el acceso a servicios de saneamiento e higiene adecuados y equitativos para todos y poner fin a la defecación al aire libre, prestando especial atención a las necesidades de las mujeres y las niñas y las personas en situaciones de vulnerabilidad', True, '2026-06-08T20:02:58.319334+00:00', '2026-07-02T04:39:21.225958+00:00'),
        (39, 8, '16.7 Garantizar la adopción en todos los niveles de decisiones inclusivas, participativas y representativas que respondan a las necesidades', True, '2026-06-08T20:02:58.325062+00:00', '2026-07-02T04:39:21.229961+00:00'),
        (40, 4, '12.7 Promover prácticas de adquisición pública que sean sostenibles, de conformidad con las políticas y prioridades nacionales', True, '2026-06-08T20:02:58.331245+00:00', '2026-07-02T04:39:21.233908+00:00'),
        (41, 9, '17.19 Para 2030, aprovechar las iniciativas existentes para elaborar indicadores que permitan medir progresos logrados en materia de desarrollo sostenible y que complementen los utilizados para medir el producto interno bruto, y apoyar el fomento de la capacidad estadística en los países en desarrollo', True, '2026-06-08T20:02:58.338305+00:00', '2026-07-02T04:39:21.237972+00:00'),
        (42, 17, '9.c Aumentar significativamente el acceso a la tecnología de la información y las comunicaciones y esforzarse por proporcionar acceso universal y asequible a Internet en los países menos adelantados de aquí a 2020', True, '2026-06-08T20:02:58.345337+00:00', '2026-07-02T04:39:21.241769+00:00'),
        (43, 12, '4.a Construir y adecuar instalaciones educativas que tengan en cuenta las necesidades de los niños y las personas con discapacidad y las diferencias de género, y que ofrezcan entornos de aprendizaje seguros, no violentos, inclusivos y eficaces para todos', True, '2026-06-08T20:02:58.352223+00:00', '2026-07-02T04:39:21.245921+00:00'),
        (44, 12, '4.3 De aquí a 2030, asegurar el acceso igualitario de todos los hombres y las mujeres a una formación técnica, profesional y superior de calidad, incluida la enseñanza universitaria', True, '2026-06-08T20:02:58.359155+00:00', '2026-07-02T04:39:21.249497+00:00'),
        (45, 16, '8.5 De aquí a 2030, lograr el empleo pleno y productivo y el trabajo decente para todas las mujeres y los hombres, incluidos los jóvenes y las personas con discapacidad, así como la igualdad de remuneración por trabajo de igual valor', True, '2026-06-08T20:02:58.365708+00:00', '2026-07-02T04:39:21.253161+00:00'),
        (46, 16, '8.8 Proteger los derechos laborales y promover un entorno de trabajo seguro y sin riesgos para todos los trabajadores, incluidos los trabajadores migrantes, en particular las mujeres migrantes y las personas con empleos precarios', True, '2026-06-08T20:02:58.372997+00:00', '2026-07-02T04:39:21.256764+00:00'),
        (47, 16, '8.9 De aquí a 2030, elaborar y poner en práctica políticas encaminadas a promover un turismo sostenible que cree puestos de trabajo y promueva la cultura y los productos locales', True, '2026-06-08T20:02:58.379784+00:00', '2026-07-02T04:39:21.260226+00:00'),
        (48, 8, '16.2 Poner fin al maltrato, la explotación, la trata, la tortura y todas las formas de violencia contra los niños', True, '2026-06-08T20:02:58.386435+00:00', '2026-07-02T04:39:21.263802+00:00'),
        (49, 2, '10.7 Facilitar la migración y la movilidad ordenadas, seguras, regulares y responsables de las personas, incluso mediante la aplicación de políticas migratorias planificadas y bien gestionadas', True, '2026-06-08T20:02:58.392509+00:00', '2026-07-02T04:39:21.267363+00:00'),
        (50, 9, '17.6 Mejorar la cooperación regional e internacional Norte-Sur, Sur-Sur y triangular en materia de ciencia, tecnología e innovación y el acceso a ellas y aumentar el intercambio de conocimientos en condiciones mutuamente convenidas, entre otras cosas mejorando la coordinación entre los mecanismos existentes, en particular en el ámbito de las Naciones Unidas, y mediante un mecanismo mundial de facilitación de la tecnología', True, '2026-06-08T20:02:58.398155+00:00', '2026-07-02T04:39:21.270748+00:00'),
        (51, 9, '17.1 Fortalecer la movilización de recursos internos, incluso mediante la prestación de apoyo internacional a los países en desarrollo, con el fin de mejorar la capacidad nacional para recaudar ingresos fiscales y de otra índole', True, '2026-06-08T20:02:58.403951+00:00', '2026-07-02T04:39:21.274977+00:00'),
        (52, 12, '4.4 De aquí a 2030, aumentar considerablemente el número de jóvenes y adultos que tienen las competencias necesarias, en particular técnicas y profesionales, para acceder al empleo, el trabajo decente y el emprendimiento', True, '2026-06-08T20:02:58.409739+00:00', '2026-07-02T04:39:21.278937+00:00'),
        (53, 16, '8.3 Promover políticas orientadas al desarrollo que apoyen las actividades productivas, la creación de puestos de trabajo decentes, el emprendimiento, la creatividad y la innovación, y fomentar la formalización y el crecimiento de las microempresas y las pequeñas y medianas empresas, incluso mediante el acceso a servicios financieros', True, '2026-06-08T20:02:58.415859+00:00', '2026-07-02T04:39:21.282487+00:00'),
        (54, 16, '8.6 De aquí a 2020, reducir considerablemente la proporción de jóvenes que no están empleados y no cursan estudios ni reciben capacitación', True, '2026-06-08T20:02:58.422354+00:00', '2026-07-02T04:39:21.286597+00:00'),
        (55, 11, '3.5 Fortalecer la prevención y el tratamiento del abuso de sustancias adictivas, incluido el uso indebido de estupefacientes y el consumo nocivo de alcohol', True, '2026-06-08T20:02:58.428781+00:00', '2026-07-02T04:39:21.290275+00:00'),
        (56, 17, '9.b Apoyar el desarrollo de tecnologías, la investigación y la innovación nacionales en los países en desarrollo, incluso garantizando un entorno normativo propicio a la diversificación industrial y la adición de valor a los productos básicos, entre otras cosas', True, '2026-06-08T20:02:58.434867+00:00', '2026-07-02T04:39:21.294+00:00'),
        (57, 8, '16.5 Reducir considerablemente la corrupción y el soborno en todas sus formas', True, '2026-06-08T20:02:58.441166+00:00', '2026-07-02T04:39:21.297679+00:00'),
        (58, 2, '10.4 Adoptar políticas, especialmente fiscales, salariales y de protección social, y lograr progresivamente una mayor igualdad', True, '2026-06-08T20:02:58.446953+00:00', '2026-07-02T04:39:21.300929+00:00'),
        (59, 3, '11.2 De aquí a 2030, proporcionar acceso a sistemas de transporte seguros, asequibles, accesibles y sostenibles para todos y mejorar la seguridad vial, en particular mediante la ampliación del transporte público, prestando especial atención a las necesidades de las personas en situación de vulnerabilidad, las mujeres, los niños, las personas con discapacidad y las personas de edad', True, '2026-06-08T20:02:58.453199+00:00', '2026-07-02T04:39:21.303905+00:00'),
        (60, 3, '11.1 De aquí a 2030, asegurar el acceso de todas las personas a viviendas y servicios básicos adecuados, seguros y asequibles y mejorar los barrios marginales', True, '2026-06-08T20:02:58.459538+00:00', '2026-07-02T04:39:21.307205+00:00'),
        (61, 1, '1.a Garantizar una movilización significativa de recursos procedentes de diversas fuentes, incluso mediante la mejora de la cooperación para el desarrollo, a fin de proporcionar medios suficientes y previsibles a los países en desarrollo, en particular los países menos adelantados, para que implementen programas y políticas encaminados a poner fin a la pobreza en todas sus dimensiones', True, '2026-06-08T20:02:58.465877+00:00', '2026-07-02T04:39:21.310251+00:00'),
        (62, 3, '11.5 De aquí a 2030, reducir significativamente el número de muertes causadas por los desastres, incluidos los relacionados con el agua, y de personas afectadas por ellos, y reducir considerablemente las pérdidas económicas directas provocadas por los desastres en comparación con el producto interno bruto mundial, haciendo especial hincapié en la protección de los pobres y las personas en situaciones de vulnerabilidad', True, '2026-06-08T20:02:58.471699+00:00', '2026-07-02T04:39:21.313431+00:00'),
        (63, 7, '15.1 De aquí a 2020, asegurar la conservación, el restablecimiento y el uso sostenible de los ecosistemas terrestres y los ecosistemas interiores de agua dulce y sus servicios, en particular los bosques, los humedales, las montañas y las zonas áridas, en consonancia con las obligaciones contraídas en virtud de acuerdos internacionales', True, '2026-06-08T20:02:58.4781+00:00', '2026-07-02T04:39:21.316775+00:00'),
        (64, 14, '6.1 De aquí a 2030, lograr el acceso universal y equitativo al agua potable a un precio asequible para todos', True, '2026-06-08T20:02:58.484142+00:00', '2026-07-02T04:39:21.320062+00:00'),
        (65, 9, '17.15 Respetar el liderazgo y el margen normativo de cada país para establecer y aplicar políticas orientadas a la erradicación de la pobreza y la promoción del desarrollo sostenible', True, '2026-06-08T20:02:58.489943+00:00', '2026-07-02T04:39:21.324075+00:00'),
        (66, 2, '10.5 Mejorar la reglamentación y vigilancia de las instituciones y los mercados financieros mundiales y fortalecer la aplicación de esos reglamentos', True, '2026-06-08T20:02:58.495744+00:00', '2026-07-02T04:39:21.328235+00:00'),
        (67, 9, '17.8 Poner en pleno funcionamiento, a más tardar en 2017, el banco de tecnología y el mecanismo de apoyo a la ciencia, la tecnología y la innovación para los países menos adelantados y aumentar la utilización de tecnología instrumental, en particular de la tecnología de la información y las comunicaciones', True, '2026-06-08T20:02:58.501493+00:00', '2026-07-02T04:39:21.33341+00:00'),
        (68, 15, '7.1 De aquí a 2030, garantizar el acceso universal a servicios energéticos asequibles, fiables y modernos', True, '2026-06-08T20:02:58.507937+00:00', '2026-07-02T04:39:21.33808+00:00'),
        (69, 3, '11.4 Redoblar los esfuerzos para proteger y salvaguardar el patrimonio cultural y natural del mundo', True, '2026-06-08T20:02:58.514111+00:00', '2026-07-02T04:39:21.341835+00:00'),
        (70, 7, '15.2 Para 2020, promover la gestión sostenible de todos los tipos de bosques, poner fin a la deforestación, recuperar los bosques degradados e incrementar la forestación y la reforestación a nivel mundial', True, '2026-06-08T20:02:58.520878+00:00', '2026-07-02T04:39:21.345438+00:00'),
        (71, 11, '3.4 De aquí a 2030, reducir en un tercio la mortalidad prematura por enfermedades no transmisibles mediante su prevención y tratamiento, y promover la salud mental y el bienestar', True, '2026-06-08T20:02:58.527021+00:00', '2026-07-02T04:39:21.349529+00:00'),
        (72, 3, '11.7 De aquí a 2030, proporcionar acceso universal a zonas verdes y espacios públicos seguros, inclusivos y accesibles, en particular para las mujeres y los niños, las personas de edad y las personas con discapacidad', True, '2026-06-08T20:02:58.533172+00:00', '2026-07-02T04:39:21.353697+00:00'),
        (73, 11, '<div>3.d Reforzar la capacidad de todos los países, en particular los países en desarrollo, en materia de alerta temprana, reducción de riesgos y gestión de los riesgos para la salud nacional y mundial</div>', True, '2026-06-08T20:02:58.539509+00:00', '2026-09-17T04:03:18.103977+00:00'),
        (74, 16, '8.2 Lograr niveles más elevados de productividad económica mediante la diversificación, la modernización tecnológica y la innovación, entre otras cosas centrándose en los sectores con gran valor añadido y un uso intensivo de la mano de obra', True, '2026-06-08T20:02:58.546373+00:00', '2026-07-02T04:39:21.362012+00:00'),
        (75, 17, '9.5 Aumentar la investigación científica y mejorar la capacidad tecnológica de los sectores industriales de todos los países, en particular los países en desarrollo, entre otras cosas fomentando la innovación y aumentando considerablemente, de aquí a 2030, el número de personas que trabajan en investigación y desarrollo por millón de habitantes y los gastos de los sectores público y privado en investigación y desarrollo', True, '2026-06-08T20:02:58.552863+00:00', '2026-07-02T04:39:21.365939+00:00'),
        (76, 17, '9.2 Promover una industrialización inclusiva y sostenible y, de aquí a 2030, aumentar significativamente la contribución de la industria al empleo y al producto interno bruto, de acuerdo con las circunstancias nacionales, y duplicar esa contribución en los países menos adelantados', True, '2026-06-08T20:02:58.559806+00:00', '2026-07-02T04:39:21.369769+00:00'),
        (77, 16, '8.a Aumentar el apoyo a la iniciativa de ayuda para el comercio en los países en desarrollo, en particular los países menos adelantados, incluso mediante el Marco Integrado Mejorado para la Asistencia Técnica a los Países Menos Adelantados en Materia de Comercio', True, '2026-06-08T20:02:58.566086+00:00', '2026-07-02T04:39:21.373366+00:00'),
        (78, 10, '2.c Adoptar medidas para asegurar el buen funcionamiento de los mercados de productos básicos alimentarios y sus derivados y facilitar el acceso oportuno a la información sobre los mercados, incluso sobre las reservas de alimentos, a fin de ayudar a limitar la extrema volatilidad de los precios de los alimentos', True, '2026-06-08T20:02:58.572597+00:00', '2026-07-02T04:39:21.377255+00:00'),
        (79, 9, '17.11 Aumentar de manera significativa las exportaciones de los países en desarrollo, en particular con miras a duplicar la participación de los países menos adelantados en las exportaciones mundiales para 2020', True, '2026-06-08T20:02:58.578887+00:00', '2026-07-02T04:39:21.380923+00:00'),
        (80, 10, '2.5 De aquí a 2020, mantener la diversidad genética de las semillas, las plantas cultivadas y los animales de granja y domesticados y sus correspondientes especies silvestres, entre otras cosas mediante una buena gestión y diversificación de los bancos de semillas y plantas a nivel nacional, regional e internacional, y promover el acceso a los beneficios que se deriven de la utilización de los recursos genéticos y los conocimientos tradicionales conexos y su distribución justa y equitativa, según lo convenido internacionalmente', True, '2026-06-08T20:02:58.584839+00:00', '2026-07-02T04:39:21.383985+00:00'),
        (81, 6, '14.4 De aquí a 2020, reglamentar eficazmente la explotación pesquera y poner fin a la pesca excesiva, la pesca ilegal, no declarada y no reglamentada y las prácticas pesqueras destructivas, y aplicar planes de gestión con fundamento científico a fin de restablecer las poblaciones de peces en el plazo más breve posible, al menos alcanzando niveles que puedan producir el máximo rendimiento sostenible de acuerdo con sus características biológicas', True, '2026-06-08T20:02:58.590727+00:00', '2026-07-02T04:39:21.387509+00:00'),
        (82, 4, '12.2 De aquí a 2030, lograr la gestión sostenible y el uso eficiente de los recursos naturales', True, '2026-06-08T20:02:58.596636+00:00', '2026-07-02T04:39:21.391227+00:00'),
        (83, 6, '14.b Facilitar el acceso de los pescadores artesanales a los recursos marinos y los mercados', True, '2026-06-08T20:02:58.60254+00:00', '2026-07-02T04:39:21.39492+00:00'),
        (84, 11, '3.c Aumentar considerablemente la financiación de la salud y la contratación, el perfeccionamiento, la capacitación y la retención del personal sanitario en los países en desarrollo, especialmente en los países menos adelantados y los pequeños Estados insulares en desarrollo', True, '2026-06-08T20:02:58.608355+00:00', '2026-07-02T04:39:21.398716+00:00'),
        (85, 11, '3.9 De aquí a 2030, reducir considerablemente el número de muertes y enfermedades causadas por productos químicos peligrosos y por la polución y contaminación del aire, el agua y el suelo', True, '2026-06-08T20:02:58.614067+00:00', '2026-07-02T04:39:21.402335+00:00'),
        (86, 11, '3.b Apoyar las actividades de investigación y desarrollo de vacunas y medicamentos contra las enfermedades transmisibles y no transmisibles que afectan primordialmente a los países en desarrollo y facilitar el acceso a medicamentos y vacunas esenciales asequibles de conformidad con la Declaración relativa al Acuerdo sobre los Aspectos de los Derechos de Propiedad Intelectual Relacionados con el Comercio y la Salud Pública, en la que se afirma el derecho de los países en desarrollo a utilizar al máximo las disposiciones del Acuerdo sobre los Aspectos de los Derechos de Propiedad Intelectual Relacionados con el Comercio respecto a la flexibilidad para proteger la salud pública y, en particular, proporcionar acceso a los medicamentos para todos', True, '2026-06-08T20:02:58.619918+00:00', '2026-07-02T04:39:21.406228+00:00'),
        (87, 14, '6.3 De aquí a 2030, mejorar la calidad del agua reduciendo la contaminación, eliminando el vertimiento y minimizando la emisión de productos químicos y materiales peligrosos, reduciendo a la mitad el porcentaje de aguas residuales sin tratar y aumentando considerablemente el reciclado y la reutilización sin riesgos a nivel mundial', True, '2026-06-08T20:02:58.62528+00:00', '2026-07-02T04:39:21.410047+00:00'),
        (88, 11, '3.3 De aquí a 2030, poner fin a las epidemias del SIDA, la tuberculosis, la malaria y las enfermedades tropicales desatendidas y combatir la hepatitis, las enfermedades transmitidas por el agua y otras enfermedades transmisibles', True, '2026-06-08T20:02:58.63068+00:00', '2026-07-02T04:39:21.413917+00:00'),
        (89, 11, '3.7 De aquí a 2030, garantizar el acceso universal a los servicios de salud sexual y reproductiva, incluidos los de planificación familiar, información y educación, y la integración de la salud reproductiva en las estrategias y los programas nacionales', True, '2026-06-08T20:02:58.636537+00:00', '2026-07-02T04:39:21.417658+00:00'),
        (90, 1, '1.3 Implementar a nivel nacional sistemas y medidas apropiados de protección social para todos, incluidos niveles mínimos, y, de aquí a 2030, lograr una amplia cobertura de las personas pobres y vulnerables', True, '2026-06-08T20:02:58.642072+00:00', '2026-07-02T04:39:21.421425+00:00'),
        (91, 15, '7.b De aquí a 2030, ampliar la infraestructura y mejorar la tecnología para prestar servicios energéticos modernos y sostenibles para todos en los países en desarrollo, en particular los países menos adelantados, los pequeños Estados insulares en desarrollo y los países en desarrollo sin litoral, en consonancia con sus respectivos programas de apoyo', True, '2026-06-08T20:02:58.647477+00:00', '2026-07-02T04:39:21.425159+00:00'),
        (92, 15, '7.2 De aquí a 2030, aumentar considerablemente la proporción de energía renovable en el conjunto de fuentes energéticas', True, '2026-06-08T20:02:58.65349+00:00', '2026-07-02T04:39:21.429037+00:00'),
        (93, 15, '7.3 De aquí a 2030, duplicar la tasa mundial de mejora de la eficiencia energética', True, '2026-06-08T20:02:58.659222+00:00', '2026-07-02T04:39:21.432551+00:00'),
        (94, 17, '9.4 De aquí a 2030, modernizar la infraestructura y reconvertir las industrias para que sean sostenibles, utilizando los recursos con mayor eficacia y promoviendo la adopción de tecnologías y procesos industriales limpios y ambientalmente racionales, y logrando que todos los países tomen medidas de acuerdo con sus capacidades respectivas', True, '2026-06-08T20:02:58.666022+00:00', '2026-07-02T04:39:21.436056+00:00'),
        (95, 16, '8.1 Mantener el crecimiento económico per cápita de conformidad con las circunstancias nacionales y, en particular, un crecimiento del producto interno bruto de al menos el 7% anual en los países menos adelantados', True, '2026-06-08T20:02:58.671515+00:00', '2026-07-02T04:39:21.440088+00:00'),
        (96, 16, '8.7 Adoptar medidas inmediatas y eficaces para erradicar el trabajo forzoso, poner fin a las formas contemporáneas de esclavitud y la trata de personas y asegurar la prohibición y eliminación de las peores formas de trabajo infantil, incluidos el reclutamiento y la utilización de niños soldados, y, de aquí a 2025, poner fin al trabajo infantil en todas sus formas', True, '2026-06-08T20:02:58.676759+00:00', '2026-07-02T04:39:21.443631+00:00'),
        (97, 15, '7.a De aquí a 2030, aumentar la cooperación internacional para facilitar el acceso a la investigación y la tecnología relativas a la energía limpia, incluidas las fuentes renovables, la eficiencia energética y las tecnologías avanzadas y menos contaminantes de combustibles fósiles, y promover la inversión en infraestructura energética y tecnologías limpias', True, '2026-06-08T20:02:58.682+00:00', '2026-07-02T04:39:21.447441+00:00'),
        (98, 4, '12.4 De aquí a 2020, lograr la gestión ecológicamente racional de los productos químicos y de todos los desechos a lo largo de su ciclo de vida, de conformidad con los marcos internacionales convenidos, y reducir significativamente su liberación a la atmósfera, el agua y el suelo a fin de minimizar sus efectos adversos en la salud humana y el medio ambiente', True, '2026-06-08T20:02:58.687538+00:00', '2026-07-02T04:39:21.451391+00:00'),
        (99, 12, '4.c De aquí a 2030, aumentar considerablemente la oferta de docentes calificados, incluso mediante la cooperación internacional para la formación de docentes en los países en desarrollo, especialmente los países menos adelantados y los pequeños Estados insulares en desarrollo', True, '2026-06-08T20:02:58.69314+00:00', '2026-07-02T04:39:21.455495+00:00'),
        (100, 12, '4.2 De aquí a 2030, asegurar que todas las niñas y todos los niños tengan acceso a servicios de atención y desarrollo en la primera infancia y educación preescolar de calidad, a fin de que estén preparados para la enseñanza primaria', True, '2026-06-08T20:02:58.698143+00:00', '2026-07-02T04:39:21.459381+00:00'),
        (101, 12, '4.6 De aquí a 2030, asegurar que todos los jóvenes y una proporción considerable de los adultos, tanto hombres como mujeres, estén alfabetizados y tengan nociones elementales de aritmética', True, '2026-06-08T20:02:58.703669+00:00', '2026-07-02T04:39:21.463348+00:00'),
        (102, 4, '12.5 De aquí a 2030, reducir considerablemente la generación de desechos mediante actividades de prevención, reducción, reciclado y reutilización', True, '2026-06-08T20:02:58.709678+00:00', '2026-07-02T04:39:21.466983+00:00'),
        (103, 3, '11.3 De aquí a 2030, aumentar la urbanización inclusiva y sostenible y la capacidad para la planificación y la gestión participativas, integradas y sostenibles de los asentamientos humanos en todos los países', True, '2026-06-08T20:02:58.715488+00:00', '2026-07-02T04:39:21.470967+00:00'),
        (104, 11, '3.6 De aquí a 2020, reducir a la mitad el número de muertes y lesiones causadas por accidentes de tráfico en el mundo', True, '2026-06-08T20:02:58.721229+00:00', '2026-07-02T04:39:21.474587+00:00'),
        (105, 8, '16.9 Para 2030, proporcionar acceso a una identidad jurídica para todos, en particular mediante el registro de nacimientos', True, '2026-06-08T20:02:58.72696+00:00', '2026-07-02T04:39:21.478305+00:00'),
        (106, 7, '15.9 De aquí a 2020, integrar los valores de los ecosistemas y la biodiversidad en la planificación, los procesos de desarrollo, las estrategias de reducción de la pobreza y la contabilidad nacionales y locales', True, '2026-06-08T20:02:58.732725+00:00', '2026-07-02T04:39:21.481855+00:00'),
        (107, 7, '15.5 Adoptar medidas urgentes y significativas para reducir la degradación de los hábitats naturales, detener la pérdida de la diversidad biológica y, para 2020, proteger las especies amenazadas y evitar su extinción', True, '2026-06-08T20:02:58.738393+00:00', '2026-07-02T04:39:21.485589+00:00'),
        (108, 7, '15.b Movilizar un volumen apreciable de recursos procedentes de todas las fuentes y a todos los niveles para financiar la gestión forestal sostenible y proporcionar incentivos adecuados a los países en desarrollo para que promuevan dicha gestión, en particular con miras a la conservación y la reforestación', True, '2026-06-08T20:02:58.744823+00:00', '2026-07-02T04:39:21.489503+00:00'),
        (109, 7, '15.3 Para 2030, luchar contra la desertificación, rehabilitar las tierras y los suelos degradados, incluidas las tierras afectadas por la desertificación, la sequía y las inundaciones, y procurar lograr un mundo con una degradación neutra del suelo', True, '2026-06-08T20:02:58.752749+00:00', '2026-07-02T04:39:21.493257+00:00'),
        (110, 7, '15.7 Adoptar medidas urgentes para poner fin a la caza furtiva y el tráfico de especies protegidas de flora y fauna y abordar la demanda y la oferta ilegales de productos silvestres', True, '2026-06-08T20:02:58.760486+00:00', '2026-07-02T04:39:21.497173+00:00'),
        (111, 4, '12.8 Velar por que las personas de todo el mundo tengan información y conocimientos pertinentes para el desarrollo sostenible', True, '2026-06-08T20:02:58.767458+00:00', '2026-07-02T04:39:21.501006+00:00'),
        (112, 14, '6.6 De aquí a 2020, proteger y restablecer los ecosistemas relacionados con el agua, incluidos los bosques, las montañas, los humedales, los ríos, los acuíferos y los lagos', True, '2026-06-08T20:02:58.775439+00:00', '2026-07-02T04:39:21.504407+00:00'),
        (113, 5, '13.2 Incorporar medidas relativas al cambio climático en las políticas, estrategias y planes nacionales', True, '2026-06-08T20:02:58.783078+00:00', '2026-07-02T04:39:21.508204+00:00'),
        (114, 4, '12.6 Alentar a las empresas, en especial las grandes empresas y las empresas transnacionales, a que adopten prácticas sostenibles e incorporen información sobre la sostenibilidad en su ciclo de presentación de informes', True, '2026-06-08T20:02:58.78926+00:00', '2026-07-02T04:39:21.512151+00:00'),
        (115, 14, '6.5 De aquí a 2030, implementar la gestión integrada de los recursos hídricos a todos los niveles, incluso mediante la cooperación transfronteriza, según proceda', True, '2026-06-08T20:02:58.795228+00:00', '2026-07-02T04:39:21.515822+00:00'),
        (116, 14, '6.4 De aquí a 2030, aumentar considerablemente el uso eficiente de los recursos hídricos en todos los sectores y asegurar la sostenibilidad de la extracción y el abastecimiento de agua dulce para hacer frente a la escasez de agua y reducir considerablemente el número de personas que sufren falta de agua', True, '2026-06-08T20:02:58.801534+00:00', '2026-07-02T04:39:21.524211+00:00'),
        (117, 5, '13.b Promover mecanismos para aumentar la capacidad de planificación y gestión eficaces en relación con el cambio climtico en los paises menos adelantados y los pequeños estados insulares', True, '2026-06-08T20:02:58.808493+00:00', '2026-07-02T04:39:21.52859+00:00'),
        (118, 6, '14.2 De aquí a 2020, gestionar y proteger sosteniblemente los ecosistemas marinos y costeros para evitar efectos adversos importantes, incluso fortaleciendo su resiliencia, y adoptar medidas para restaurarlos a fin de restablecer la salud y la productividad de los océanos', True, '2026-06-08T20:02:58.815+00:00', '2026-07-02T04:39:21.532557+00:00'),
        (119, 7, '15.8 De aquí a 2020, adoptar medidas para prevenir la introducción de especies exóticas invasoras y reducir significativamente sus efectos en los ecosistemas terrestres y acuáticos y controlar o erradicar las especies prioritarias', True, '2026-06-08T20:02:58.821259+00:00', '2026-07-02T04:39:21.536388+00:00'),
        (120, 6, '14.c Mejorar la conservación y el uso sostenible de los oceanos y sus recursos aplicando el derecho internacional reflejado en la convención del Derecho del Mar', True, '2026-06-08T20:02:58.827555+00:00', '2026-07-02T04:39:21.540344+00:00'),
        (121, 4, '12.b Elaborar y aplicar instrumentos para vigilar los efectos en el desarrollo sostenible, a fin de lograr un turismo sostenible que cree puestos de trabajo y promueva la cultura y los productos locales', True, '2026-06-08T20:02:58.833929+00:00', '2026-07-02T04:39:21.543867+00:00'),
        (122, 9, '17.10 Promover un sistema de comercio multilateral universal, basado en normas, abierto, no discriminatorio y equitativo en el marco de la Organización Mundial del Comercio, incluso mediante la conclusión de las negociaciones con arreglo a su Programa de Doha para el Desarrollo', True, '2026-06-08T20:02:58.841271+00:00', '2026-07-02T04:39:21.54726+00:00'),
        (123, 17, '9.3 Aumentar el acceso de las pequeñas industrias y otras empresas, particularmente en los países en desarrollo, a los servicios financieros, incluidos créditos asequibles, y su integración en las cadenas de valor y los mercados', True, '2026-06-08T20:02:58.848252+00:00', '2026-07-02T04:39:21.550516+00:00'),
        (124, 6, '14.5 De aquí a 2020, conservar al menos el 10% de las zonas costeras y marinas, de conformidad con las leyes nacionales y el derecho internacional y sobre la base de la mejor información científica disponible', True, '2026-06-08T20:02:58.855161+00:00', '2026-07-02T04:39:21.553893+00:00'),
        (125, 13, '5.5 Asegurar la participación plena y efectiva de las mujeres y la igualdad de oportunidades de liderazgo a todos los niveles decisorios en la vida política, económica y pública', True, '2026-06-08T20:02:58.861508+00:00', '2026-07-02T04:39:21.55706+00:00'),
        (126, 3, '11.6 De aquí a 2030, reducir el impacto ambiental negativo per cápita de las ciudades, incluso prestando especial atención a la calidad del aire y la gestión de los desechos municipales y de otro tipo', True, '2026-06-08T20:02:58.867838+00:00', '2026-07-02T04:39:21.560389+00:00'),
        (127, 1, '1.1 De aquí a 2030, erradicar para todas las personas y en todo el mundo la pobreza extrema (actualmente se considera que sufren pobreza extrema las personas que viven con menos de 1,25 dólares de los Estados Unidos al día)', True, '2026-06-08T20:02:58.87439+00:00', '2026-07-02T04:39:21.563745+00:00'),
        (128, 10, '2.1 De aquí a 2030, poner fin al hambre y asegurar el acceso de todas las personas, en particular los pobres y las personas en situaciones de vulnerabilidad, incluidos los niños menores de 1 año, a una alimentación sana, nutritiva y suficiente durante todo el año', True, '2026-06-08T20:02:58.880523+00:00', '2026-07-02T04:39:21.567496+00:00'),
        (129, 8, '16.8 Ampliar y fortalecer la participación de los países en desarrollo en las instituciones de gobernanza mundial', True, '2026-06-08T20:02:58.887589+00:00', '2026-07-02T04:39:21.57112+00:00'),
        (130, 13, '5.a Emprender reformas que otorguen a las mujeres igualdad de derechos a los recursos económicos, así como acceso a la propiedad y al control de la tierra y otros tipos de bienes, los servicios financieros, la herencia y los recursos naturales, de conformidad con las leyes nacionales', True, '2026-06-08T20:02:58.893873+00:00', '2026-07-02T04:39:21.574762+00:00'),
        (131, None, '', True, '2026-07-02T04:39:21.580322+00:00', '2026-07-02T04:39:21.580341+00:00'),
    ],
)

